# ---------------------------------------------------------------------------
# Proxies: let generated code write xl.Range("A1").Select()
# ---------------------------------------------------------------------------


class Obj:
    """A VBA object (Range, Worksheet, ...) seen from Python."""

    __slots__ = ("_o",)

    def __init__(self, o):
        object.__setattr__(self, "_o", o)

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return Member(self._o, name)

    def __setattr__(self, name, value):
        _let_member(self._o, name, value)

    def __call__(self, *args, **kwargs):
        return wrap(index_value(self._o, [raw(a) for a in args], _kw(kwargs)))

    def __repr__(self):
        return f"Obj({self._o!r})"


class Member:
    """obj.Name before we know whether it is called with arguments."""

    __slots__ = ("_o", "_n")

    def __init__(self, o, name):
        object.__setattr__(self, "_o", o)
        object.__setattr__(self, "_n", name)

    def _get(self):
        return member_value(self._o, self._n, [], {})

    def __call__(self, *args, **kwargs):
        return wrap(member_value(self._o, self._n, [raw(a) for a in args], _kw(kwargs)))

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return Member(raw(self._get()), name)

    def __setattr__(self, name, value):
        _let_member(raw(self._get()), name, value)

    def __repr__(self):
        return f"Member({self._o!r}.{self._n})"


class Arr:
    """A VBA array variable: v.a[i, j] reads and writes elements with VBA's rules."""

    __slots__ = ("_a",)

    def __init__(self, a):
        object.__setattr__(self, "_a", a)

    def _idx(self, key):
        key = key if isinstance(key, tuple) else (key,)
        return [to_long(val(k)) for k in key]

    def __getitem__(self, key):
        return wrap(self._a.get(self._idx(key)))

    def __setitem__(self, key, value):
        x = raw(value)
        if not isinstance(x, VBAObject):
            x = coerce(default_value(x), self._a.elem_type)
        self._a.set(self._idx(key), x)


def _kw(kwargs):
    return {k.lower(): raw(v) for k, v in kwargs.items()}


def wrap(x):
    if isinstance(x, VBAObject):
        return Obj(x)
    if isinstance(x, VBAArray):
        return Arr(x)
    return x


def raw(x):
    """The underlying VBA value or object."""
    while True:
        if isinstance(x, Obj):
            return x._o
        if isinstance(x, Member):
            x = x._get()
            continue
        if isinstance(x, Arr):
            return x._a
        return x


def val(x):
    """The value of x, an object giving its default property (Range -> Value)."""
    return default_value(raw(x))


def member_value(o, name, args, kwargs):
    if o is NOTHING:
        raise VBARuntimeError(91, "Object variable or With block variable not set")
    if not isinstance(o, VBAObject):
        raise VBARuntimeError(424, "Object required")
    return o.vba_member(name, args, kwargs)


def _let_member(o, name, value):
    o = raw(o)
    if o is NOTHING:
        raise VBARuntimeError(91, "Object variable or With block variable not set")
    if not isinstance(o, VBAObject):
        raise VBARuntimeError(424, "Object required")
    o.vba_let_member(name, [], {}, raw(value))


def member(obj, name, *args, **kwargs):
    """obj.<name>(args) for member names that Python keeps for itself, or that its own numbers and text answer to."""
    return wrap(member_value(raw(obj), name, [raw(a) for a in args], _kw(kwargs)))


def index(x, *args, **kwargs):
    """x(args) where x is a variable: an array element or an object's default member."""
    return wrap(index_value(raw(x), [raw(a) for a in args], _kw(kwargs)))


def let(target, value):
    """Assign to an object's default member: Cells(1, 2) = value."""
    o = raw(target)
    if not isinstance(o, VBAObject):
        raise VBARuntimeError(424, "Object required")
    o.vba_default_let(raw(value))


def mid_statement(text, start, length, new):
    """What Mid(text, start, length) = new leaves in the variable: `new` written over part of the text, as far as
    the length asked for, the new text and the old one's end all allow."""
    text, new, start = _builtins.to_str(val(text)), _builtins.to_str(val(new)), to_long(val(start))
    if not 1 <= start <= len(text):
        raise VBARuntimeError(5, "Invalid procedure call or argument")
    room = len(text) - start + 1
    count = min(len(new), room) if length is None else min(to_long(val(length)), len(new), room)
    return text[: start - 1] + new[:count] + text[start - 1 + count :]


def let_index(holder, key, value):
    """x(i) = value where x is a Variant that may hold an array or an object."""
    x = raw(holder)
    if isinstance(x, VBAArray):
        Arr(x)[key] = value
        return
    if isinstance(x, VBAObject):
        keys = key if isinstance(key, tuple) else (key,)
        target = x.vba_index([raw(k) for k in keys], {})
        let(target, value)
        return
    raise VBARuntimeError(13, "Type mismatch")


# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------


class Var:
    __slots__ = ("value", "type_name")

    def __init__(self, value, type_name="variant"):
        self.value = value
        self.type_name = type_name

    def let(self, value):
        self.value = coerce(value, self.type_name)


def _new_var(decl):
    name, bounds, dynamic, type_name = decl
    if bounds is not None:
        return Var(VBAArray([tuple(b) for b in bounds], type_name), "array")
    if dynamic:
        return Var(VBAArray(None, type_name), "array")
    return Var(default_for_type(type_name), type_name)


class _Scope:
    def _find(self, key):
        raise NotImplementedError

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return self[name]

    def __getitem__(self, name):
        var = self._find(name.lower())
        return wrap(var.value)

    def __setattr__(self, name, value):
        self[name] = value

    def __setitem__(self, name, value):
        var = self._find(name.lower())
        x = raw(value)
        if isinstance(x, VBAArray) and normalise_type(var.type_name) in ("variant", "array"):
            var.value = x.copy()
            return
        if var.type_name == "array":
            raise VBACompileError(f"Can't assign to array: {name}")
        var.let(default_value(x))


class Module(_Scope):
    """Variables declared at the top of a VBA module; they persist between macros."""

    def __init__(
        self, name, decls=(), option_compare_text=False, option_explicit=False, kind="standard", option_base=0
    ):
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_vars", {d[0].lower(): _new_var(d) for d in decls})
        object.__setattr__(self, "_text", option_compare_text)
        object.__setattr__(self, "_explicit", option_explicit)
        object.__setattr__(self, "_base", option_base)  # where Array(...) starts: Option Base
        object.__setattr__(self, "_kind", kind)  # "document": a sheet's module

    def _find(self, key):
        if key in self._vars:
            return self._vars[key]
        raise VBACompileError(f"Variable not defined: {self._name}.{key}")


class Frame(_Scope):
    """The variables of one procedure call."""

    def __init__(self, ctx, module, proc, decls=(), params=(), args=(), kwargs=None, returns=None):
        tick()
        object.__setattr__(self, "_ctx", ctx)
        object.__setattr__(self, "_module", module)
        object.__setattr__(self, "_proc", proc)
        object.__setattr__(self, "_vars", {})
        object.__setattr__(self, "_on_error", None)
        object.__setattr__(self, "_in_handler", False)
        object.__setattr__(self, "_resume_pc", None)
        _bind(self, params, list(args), {k.lower(): a for k, a in (kwargs or {}).items()})
        if returns is not None:
            self._vars[returns[0].lower()] = Var(default_for_type(returns[1]), returns[1])
        for d in decls:
            key = d[0].lower()
            if key in self._vars:
                continue
            if len(d) > 4 and d[4]:  # Static: one variable for every call
                skey = (module._name.lower(), proc.lower(), key)
                if skey not in ctx.statics:
                    ctx.statics[skey] = _new_var(d[:4])
                self._vars[key] = ctx.statics[skey]
            else:
                self._vars[key] = _new_var(d[:4])

    def _find(self, key):
        if key in self._vars:
            return self._vars[key]
        if key in self._module._vars:
            return self._module._vars[key]
        if self._module._explicit:
            raise VBACompileError(f"Variable not defined: {key}")
        var = self._vars[key] = Var(EMPTY)
        return var


class Ref:
    """A variable passed ByRef to another procedure."""

    __slots__ = ("var",)

    def __init__(self, var):
        self.var = var


def ref(scope, name):
    return Ref(scope._find(name.lower()))


class ItemVar:
    """An element of an array passed ByRef: the procedure's parameter is that element."""

    __slots__ = ("array", "index")

    def __init__(self, array, index):
        self.array, self.index = array, index

    type_name = property(lambda self: self.array.elem_type)
    value = property(lambda self: self.array.get(self.index), lambda self, x: self.array.set(self.index, x))

    def let(self, value):
        self.array.set(self.index, coerce(value, self.array.elem_type))


def ref_item(holder, *index):
    """a(i) as an argument: the element itself when a is an array, so a ByRef parameter changes it."""
    x = raw(holder)
    if isinstance(x, VBAArray):
        return Ref(ItemVar(x, [to_long(val(i)) for i in index]))
    return wrap(index_value(x, [raw(i) for i in index]))


def _bind(frame, params, args, kwargs):
    for i, (name, byval, optional, default, type_name, paramarray) in enumerate(params):
        if paramarray:
            rest = [val(a.var.value if isinstance(a, Ref) else a) for a in args[i:]]
            frame._vars[name.lower()] = Var(VBAArray.from_list(rest), "variant")
            return
        a = args[i] if i < len(args) else kwargs.get(name.lower())
        if a is None:
            if not optional:
                raise VBACompileError(f"{frame._proc}: argument {name} not optional")
            if default is not None:
                value = default
            elif normalise_type(type_name) == "variant":
                value = MISSING
            else:
                value = default_for_type(type_name)
            frame._vars[name.lower()] = Var(value, type_name)
            continue
        if isinstance(a, Ref):
            if not byval:
                frame._vars[name.lower()] = a.var
                continue
            a = a.var.value
        x = raw(a)
        if isinstance(x, VBAArray):
            x = x.copy()  # by value: the procedure gets its own array
        from .values import is_object_type

        if is_object_type(type_name) or (isinstance(x, VBAObject) and normalise_type(type_name) == "variant"):
            frame._vars[name.lower()] = Var(x, type_name)
        else:
            var = Var(default_for_type(type_name), type_name)
            var.let(default_value(x) if not isinstance(x, VBAArray) else x)
            frame._vars[name.lower()] = var


def set_(scope, name, value):
    """Set name = object."""
    x = raw(value)
    if not (isinstance(x, VBAObject) or x is NOTHING):
        raise VBARuntimeError(424, "Object required")
    scope._find(name.lower()).value = x


def result(frame, name):
    """What a Function returns: as a variable gives it, so GetSheet("Data").Range("A1") works on the result."""
    return wrap(frame._vars[name.lower()].value)


def redim(frame, name, bounds, preserve=False, type_name="variant"):
    var = frame._find(name.lower())
    if not isinstance(var.value, VBAArray):
        var.value, var.type_name = VBAArray(None, type_name), "array"
    var.value.redim([(to_long(val(lo)), to_long(val(hi))) for lo, hi in bounds], preserve)


def erase(frame, name):
    var = frame._find(name.lower())
    if not isinstance(var.value, VBAArray):
        raise VBARuntimeError(13, "Type mismatch")
    if var.type_name == "array" and var.value.bounds is not None:
        var.value.data = {}
    else:
        var.value.bounds, var.value.data = None, {}


# ---------------------------------------------------------------------------
# Operators and conditions
# ---------------------------------------------------------------------------


# Comparisons. k says how the two sides are declared, which decides how a number is compared with a string:
# "n" a numeric type, "s" a String, "v" a Variant (see values.compare).


def _cmp(a, b, text, k):
    return compare(val(a), val(b), text, k)


def eq(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c == 0


def ne(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c != 0


def lt(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c < 0


def gt(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c > 0


def le(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c <= 0


def ge(a, b, text=False, k="vv"):
    c = _cmp(a, b, text, k)
    return NULL if c is NULL else c >= 0


def like(a, b, text=False):
    if val(a) is NULL or val(b) is NULL:
        return NULL
    return _like(val(a), val(b), text)


def is_(a, b):
    return raw(a) is raw(b)


def add(a, b):
    return op_add(val(a), val(b))


def sub(a, b):
    return op_sub(val(a), val(b))


def mul(a, b):
    return op_mul(val(a), val(b))


def div(a, b):
    return op_div(val(a), val(b))


def idiv(a, b):
    return op_intdiv(val(a), val(b))


def mod(a, b):
    return op_mod(val(a), val(b))


def pow_(a, b):
    return op_pow(val(a), val(b))


def cat(a, b):
    return op_concat(val(a), val(b))


def neg(a):
    return op_neg(val(a))


def not_(a):
    return op_not(val(a))


def and_(a, b):
    return op_and(val(a), val(b))


def or_(a, b):
    return op_or(val(a), val(b))


def xor(a, b):
    return op_xor(val(a), val(b))


def eqv(a, b):
    return op_eqv(val(a), val(b))


def imp(a, b):
    return op_imp(val(a), val(b))


def cond(x):
    """The test of If / While / Do: VBA rules, Null counts as False."""
    tick()
    return condition_true(val(x))


def num(x):
    return to_number(val(x))


def for_test(counter, end, step):
    tick()
    c = to_number(val(counter))
    return c <= end if step >= 0 else c >= end


def each(collection):
    x = raw(collection)
    if isinstance(x, VBAArray):
        return [wrap(i) for i in x.iter_all()]
    if isinstance(x, VBAObject):
        return [wrap(i) for i in x.vba_iter()]
    raise VBARuntimeError(424, "Object required")


def assign_each(scope, name, item):
    tick()
    if isinstance(raw(item), VBAObject):
        set_(scope, name, item)
    else:
        scope[name] = item


def case_eq(subject, x, text=False, k="vv"):
    return _cmp(subject, x, text, k) == 0


def case_range(subject, lo, hi, text=False, k="vvv"):
    """Case lo To hi; k is how the subject, lo and hi are declared."""
    return _cmp(subject, lo, text, k[0] + k[1]) >= 0 and _cmp(subject, hi, text, k[0] + k[2]) <= 0


# ---------------------------------------------------------------------------
# Errors (On Error Resume Next / GoTo)
# ---------------------------------------------------------------------------


def on_error():
    _CTX.err.clear()


CAUGHT = (VBARuntimeError, AttributeError)  # what On Error can handle: see vba_error
_HERE = _os.path.dirname(_os.path.abspath(__file__))


def vba_error(err):
    """The VBA error a failure in converted code stands for. A member asked there of a number or of text (x.Value,
    x holding 5) is Python's AttributeError and VBA's error 424. One raised inside this package is a fault of the
    converter, not of the macro, and is passed on as it is."""
    if isinstance(err, VBARuntimeError):
        return err
    tb = err.__traceback__
    while tb.tb_next is not None:
        tb = tb.tb_next
    if _os.path.abspath(tb.tb_frame.f_code.co_filename).startswith(_HERE + _os.sep):
        raise err
    return VBARuntimeError(424, "Object required")


def skipped(err, line):
    """A statement failed under On Error Resume Next: record it and carry on."""
    err = vba_error(err)
    _CTX.err.set(err.number, err.description)
    _CTX.ledger.note("ON-ERROR-RESUME-NEXT", f"line {line}: {err.description}")


def cond_rn(fn, on_error_value, line):
    """A condition under On Error Resume Next: if it fails, VBA runs the next statement."""
    try:
        return cond(fn())
    except CAUGHT as err:
        skipped(err, line)
        return on_error_value


def try_value(fn, default, line):
    try:
        return fn()
    except CAUGHT as err:
        skipped(err, line)
        return default


def header(fn, line):
    """A loop or Select header under On Error Resume Next: a failure is not modelled."""
    try:
        return fn()
    except CAUGHT as err:
        err = vba_error(err)
        raise VBANotImplemented(
            f"line {line}: a loop or Select header failed under On Error Resume Next "
            f"({err.description}); VBA's behaviour here is not modelled"
        ) from err


def not_modelled(text):
    raise VBANotImplemented(text)


# --- support for procedures generated as a list of steps (GoTo, On Error GoTo) ---


def jump(w, depth, target):
    tick()
    d = depth[target] if target < len(depth) else 0
    if d > len(w):
        raise VBANotImplemented("jumping into a With block")
    del w[d:]
    return target


def set_on_error(frame, mode, label_pc=None):
    _CTX.err.clear()
    object.__setattr__(frame, "_in_handler", False)
    object.__setattr__(frame, "_on_error", None if mode is None else (mode, label_pc))


def handle_error(frame, err, pc, w, depth, kind):
    err = vba_error(err)
    mode = frame._on_error
    if mode is None or (frame._in_handler and mode[0] != "resume_next"):
        raise err
    if kind in ("for_init", "for_test", "for_next", "each_init", "each_next", "select"):
        raise VBANotImplemented(
            f"a loop or Select header failed under On Error ({err.description}); VBA's behaviour here is not modelled"
        ) from err
    _CTX.err.set(err.number, err.description)
    if mode[0] == "resume_next":
        _CTX.ledger.note("ON-ERROR-RESUME-NEXT", f"{frame._proc}: {err.description}")
        return pc + 1
    object.__setattr__(frame, "_in_handler", True)
    object.__setattr__(frame, "_resume_pc", pc)
    return jump(w, depth, mode[1])


def resume(frame, kind, target, w, depth):
    if not frame._in_handler:
        raise VBARuntimeError(20, "Resume without error")
    object.__setattr__(frame, "_in_handler", False)
    _CTX.err.clear()
    if kind == "resume":
        pc = frame._resume_pc
    elif kind == "next":
        pc = frame._resume_pc + 1
    else:
        pc = target
    return jump(w, depth, pc)


def for_init(scope, name, start, end, step):
    scope[name] = val(start)
    return (to_number(val(end)), to_number(val(step)))


def for_ok(scope, name, state, key):
    if key not in state:
        raise VBARuntimeError(92, "For loop not initialized")
    end, step = state[key]
    return for_test(scope[name], end, step)


def step(scope, name, step_value):
    """Next: add the step to the loop counter."""
    scope[name] = add(scope[name], step_value)


def for_next(scope, name, state, key):
    if key not in state:
        raise VBARuntimeError(92, "For loop not initialized")
    scope[name] = add(scope[name], state[key][1])


def each_next(scope, name, state, key):
    tick()
    items, i = state[key]
    if i >= len(items):
        return False
    state[key][1] = i + 1
    assign_each(scope, name, items[i])
    return True


# ---------------------------------------------------------------------------
# Built-in functions and constants: rt.Left(...), rt.Now(), rt.xlDown
# ---------------------------------------------------------------------------


def __getattr__(name):
    key = name.lower()
    if key in BUILTINS:
        fn = BUILTINS[key]

        def call(*args, _frame=None, **kwargs):  # _frame: the calling procedure's, for its module's Option Compare
            return wrap(fn(_CTX, _frame, [raw(a) for a in args], _kw(kwargs)))

        call.__name__ = name
        return call
    if key in XL_CONSTANTS:
        return XL_CONSTANTS[key]
    if key in VB_CONSTANTS:
        return VB_CONSTANTS[key]
    raise AttributeError(name)


def datetime(*parts):
    return _dt.datetime(*parts)


def scope(ctx, module):
    """A sheet module's own sheet, for its Range, Cells, Rows and Columns without a qualifier, as Excel reads them."""
    return Obj(ctx.app.globals_for(module))


def codename(ctx, name):
    """The sheet with this code name: Sheet1 in Sheet1.Range("A1"), and Me in Sheet1's own module."""
    sheet = ctx.book.sheet_by_codename(name)
    if sheet is None:
        raise VBARuntimeError(424, "Object required")
    return Obj(sheet)


# ---------------------------------------------------------------------------
# Session
# ---------------------------------------------------------------------------


class Clock:
    """The run's time. It starts at the run's Now and passes only as the macro looks at it or waits: 1 ms each time
    Now, Date, Time or Timer is read, and up to the time Application.Wait names. A loop waiting for the time to pass
    ends, and the timestamps one run writes stay as they were (Now has whole seconds)."""

    def __init__(self, start):
        self.start, self.elapsed = start, 0.0

    def read(self):
        self.elapsed += 0.001
        return self.start + _dt.timedelta(seconds=self.elapsed)

    def wait_until(self, when):
        self.elapsed = max(self.elapsed, (when - self.start).total_seconds())


_TICKS = 0


def tick():
    """Called where a macro can loop: stops a run that has passed its time limit."""
    global _TICKS
    _TICKS += 1
    if not _TICKS & 255 and _CTX.deadline is not None and _time.monotonic() > _CTX.deadline:
        raise VBATimeout(f"the run passed its time limit of {_CTX.timeout:g} seconds")


@contextlib.contextmanager
def deep_calls():
    """While macros run: room for procedures that call themselves a few thousand deep, as VBA allows."""
    limit = sys.getrecursionlimit()
    sys.setrecursionlimit(max(limit, 12000))
    try:
        yield
    finally:
        sys.setrecursionlimit(limit)


def run_macro(fn, ctx):
    """Run one converted macro. Returns its outcome as (status, message): what stops it is told, never raised."""
    global _CTX
    _CTX = ctx
    _values.set_note(ctx.ledger.note)
    if ctx.timeout is not None and ctx.deadline is None:
        ctx.deadline = _time.monotonic() + ctx.timeout
    try:
        with deep_calls():
            fn(ctx)
    except VBAEnd:
        pass
    except CAUGHT as err:
        try:
            return "stopped by a VBA error", str(vba_error(err))
        except AttributeError:  # raised inside the converter
            return "stopped: converter error", f"{type(err).__name__}: {err}"
    except RecursionError:
        return "stopped by a VBA error", "run-time error 28: Out of stack space"
    except VBATimeout as err:
        return "stopped: time limit", str(err)
    except VBAError as err:
        return "stopped: not modelled", str(err)
    except Exception as err:  # noqa: BLE001 - a fault in the converter stops this macro, not the run
        return "stopped: converter error", f"{type(err).__name__}: {err}"
    return "completed", ""


class Context:
    """One Excel session on one workbook: `xl` in generated code."""

    def __init__(self, workbook_path=None, book=None, now=None, answers=(), environ=None, timeout=None):
        global _CTX
        self.path = workbook_path
        self.book = book if book is not None else read_workbook(workbook_path)
        self.ledger = Ledger()
        _values.set_note(self.ledger.note)
        self.timeout = timeout  # seconds the macros may run in all, or None
        self.deadline = None  # when that time is up: counted from the first macro's start
        self.now = now or _dt.datetime.now().replace(microsecond=0)
        self.clock = Clock(self.now)
        self.app = Application(self.book, self.ledger, self.clock)
        self.book.now = self.now
        self.answers = list(answers)
        self.environ = dict(environ or {})
        self.messages = []
        self.err = ErrObject()
        self.debug = DebugObject(self)
        self.statics = {}
        self._globals = self.app.globals_for(None)
        _CTX = self

    def text_compare(self, frame=None):
        """Option Compare Text: a setting of the module whose code is running, which hands its frame to the builtins
        that take a Compare argument (operators and Select Case get it from the generated code)."""
        return frame is not None and frame._module._text

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        key = name.lower()
        if key == "err":
            return Obj(self.err)
        if key == "debug":
            return Obj(self.debug)
        return Member(self._globals, name)

    def save(self, out_path):
        from .writer import save_workbook

        return save_workbook(self.book, self.path, out_path)

    def snapshot(self):
        return _snapshot.take(self.book)


class _Step(argparse.Action):
    def __call__(self, parser, namespace, values, option_string=None):
        steps = getattr(namespace, "steps", None) or []
        steps.append((self.dest, values))
        namespace.steps = steps


def main(buttons, macros, description="", argv=None):
    """Command line of a generated file: run buttons/macros on a workbook and save the result."""
    ap = argparse.ArgumentParser(description=description, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("input", help="the workbook to run on (.xlsm/.xlsx); it is not modified")
    ap.add_argument("output", help="where to save the updated workbook")
    ap.add_argument("--button", action=_Step, dest="button", help="button caption to press (repeatable, in order)")
    ap.add_argument("--macro", action=_Step, dest="macro", help="macro name to run (repeatable, in order)")
    ap.add_argument("--now", help="value of Now(), 'YYYY-MM-DD HH:MM:SS'")
    ap.add_argument("--answer", action="append", help="answer for the next MsgBox/InputBox question")
    ap.add_argument("--env", action="append", metavar="NAME=VALUE", help='what Environ("NAME") gives (repeatable)')
    ap.add_argument("--timeout", type=float, help="seconds the macros may run in all")
    args = ap.parse_args(argv)
    steps = getattr(args, "steps", None) or []
    if not steps:
        ap.error("choose at least one --button or --macro. Buttons: " + ", ".join(repr(b) for b in buttons))
    now = _dt.datetime.strptime(args.now, "%Y-%m-%d %H:%M:%S") if args.now else None
    environ = dict(item.split("=", 1) for item in args.env or [] if "=" in item)
    ctx = Context(args.input, now=now, answers=args.answer or [], environ=environ, timeout=args.timeout)
    status = 0
    for i, (kind, name) in enumerate(steps, 1):
        table = buttons if kind == "button" else macros
        if name not in table:
            ap.error(f"unknown {kind} {name!r}; choose from: " + ", ".join(repr(k) for k in table))
        outcome, message = run_macro(table[name], ctx)
        print(f"[{i}] {kind} {name!r}: {outcome}" + (f": {message}" if message else ""))
        if outcome != "completed":
            status = 1
            break
    ctx.save(args.output)
    print(f"saved {args.output}")
    for line in ctx.ledger.report_lines():
        print(line)
    for kind, text in ctx.messages:
        print(f"{kind}: {text}")
    return status
